# -*- coding: utf-8 -*-
"""
Al-othmany Sender 3.5.3 - ALL IN ONE REQUEST/JOIN FIX

Single upload patch for the Android source repository.
It includes/retains:
- 3.5.1 Shizuku continuity + false-pause hotfix
- 3.5.2 exact real dashboard UI
- 3.5.2 R1 Kotlin/validator build fixes
- 3.5.3 robust Request-to-Join execution for Accessibility + Shizuku
- screenshot-matched real Android dashboard from the supplied reference
- bounded visual rescue when WhatsApp exposes a visible button but ignores/omits semantic click nodes
- conservative request result verification (no false REQUESTED count)

Accepted source states: 3.5.0 / 3.5.1 / 3.5.2 / 3.5.3.
Final version: 3.5.3 / versionCode 353.
"""
from pathlib import Path
import base64
import traceback

ROOT = Path.cwd()
if not (ROOT / "app").is_dir():
    raise SystemExit("ERROR: run from the Android repository root (for example /workspaces/AL-thmany-2.8.0)")

BASE_MERGED_B64 = ""
changed = []

def p(rel: str) -> Path:
    q = ROOT / rel
    if not q.exists():
        raise SystemExit(f"ERROR: missing required file: {rel}")
    return q

def read(rel: str) -> str:
    return p(rel).read_text(encoding="utf-8")

def write(rel: str, text: str) -> None:
    q = p(rel)
    old = q.read_text(encoding="utf-8")
    if old != text:
        q.write_text(text, encoding="utf-8")
        changed.append(rel)

def run_embedded(label: str, payload_b64: str) -> None:
    print("\n" + "=" * 72)
    print(label)
    print("=" * 72)
    source = base64.b64decode(payload_b64).decode("utf-8")
    ns = {"__name__": "__main__", "__file__": f"<embedded:{label}>"}
    try:
        exec(compile(source, ns["__file__"], "exec"), ns, ns)
    except SystemExit:
        raise
    except Exception:
        traceback.print_exc()
        raise SystemExit(f"ERROR while applying embedded stage: {label}")

