def _ensure_color(name: str, value: str) -> None:
    src = read(colors_rel)
    pat = _re.compile(rf'(<color\s+name="{_re.escape(name)}">)(.*?)(</color>)')
    if pat.search(src):
        src = pat.sub(lambda m: m.group(1) + value + m.group(3), src, count=1)
    else:
        src = src.replace("</resources>", f'    <color name="{name}">{value}</color>\n</resources>', 1)
    write(colors_rel, src)


def _ensure_text_file(rel: str, text: str) -> None:
    q = ROOT / rel
    q.parent.mkdir(parents=True, exist_ok=True)
    old = q.read_text(encoding="utf-8") if q.exists() else None
    if old != text:
        q.write_text(text, encoding="utf-8")
        if rel not in changed:
            changed.append(rel)


def _ensure_binary_file(rel: str, payload_b64: str) -> None:
    q = ROOT / rel
    q.parent.mkdir(parents=True, exist_ok=True)
    data = base64.b64decode(payload_b64)
    old = q.read_bytes() if q.exists() else None
    if old != data:
        q.write_bytes(data)
        if rel not in changed:
            changed.append(rel)


